// Expected input: { lead_id, diagnostic_id }
// We re-fetch the diagnostic from Supabase rather than trusting the webhook
// payload — single source of truth.

const input = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};
if (headers['x-webhook-secret'] !== $vars.WEBHOOK_SECRET) {
  throw new Error('Unauthorized');
}

if (!input.lead_id || !input.diagnostic_id) {
  throw new Error('Required: lead_id and diagnostic_id');
}

return [{ json: { lead_id: input.lead_id, diagnostic_id: input.diagnostic_id } }];

// Build the prompt input from the joined query.
const rows = $input.first().json;
const row = Array.isArray(rows) ? rows[0] : rows;
if (!row) throw new Error('Diagnostic not found');

const lead = row.consulting_leads || {};
const diag = row.raw_response || {};
const tasks = diag.tasks || [];
if (tasks.length < 3) throw new Error('Diagnostic has fewer than 3 tasks');

// Pick accent color by sector (used in the prompt to guide Claude).
const sector = (lead.business_sector || '').toLowerCase();
const accentMap = {
  'hotellerie': '#d4af37', 'hôtellerie': '#d4af37', 'hotel': '#d4af37',
  'restauration': '#e07b39', 'restaurant': '#e07b39',
  'sante': '#3b82f6', 'santé': '#3b82f6', 'medical': '#3b82f6', 'dentaire': '#3b82f6',
  'immobilier': '#10b981', 'realestate': '#10b981',
  'beaute': '#ec4899', 'beauté': '#ec4899', 'esthetique': '#ec4899'
};
const accent = accentMap[sector] || '#6366f1';

return [{
  json: {
    lead_id: row.lead_id,
    diagnostic_id: row.id,
    business_name: lead.business_name,
    business_url: lead.business_url,
    sector: lead.business_sector,
    accent_color: accent,
    total_cost_annual: row.total_cost_annual,
    total_hours_lost_weekly: row.total_hours_lost_weekly,
    task_1: tasks[0],
    task_2: tasks[1],
    task_3: tasks[2]
  }
}];

const response = $input.first().json;
const ctx = $('Build prompt context').first().json;

let html;
try {
  html = response.content[0].text;
} catch (e) {
  throw new Error('Claude response missing content[0].text');
}

// Strip stray markdown fences.
html = html.trim().replace(/^```(?:html)?\s*/, '').replace(/```\s*$/, '');

if (!html.toLowerCase().includes('<!doctype html') && !html.toLowerCase().includes('<html')) {
  throw new Error('Output is not valid HTML — got: ' + html.slice(0, 300));
}

const usage = response.usage || {};
const inTok = usage.input_tokens || 0;
const outTok = usage.output_tokens || 0;
const costUsd = (inTok / 1e6) * 3 + (outTok / 1e6) * 15;

return [{
  json: {
    lead_id: ctx.lead_id,
    diagnostic_id: ctx.diagnostic_id,
    business_name: ctx.business_name,
    html_content: html,
    tokens_in: inTok,
    tokens_out: outTok,
    api_cost_usd: Number(costUsd.toFixed(4))
  }
}];

// Upload HTML to Supabase Storage to get a public URL.
// Filename: schemas/<lead_id>/<schema_id>.html
const rows = $input.first().json;
const row = Array.isArray(rows) ? rows[0] : rows;
if (!row || !row.id) throw new Error('Failed to insert schema row');

const ctx = $('Validate HTML').first().json;
const path = `schemas/${ctx.lead_id}/${row.id}.html`;
const publicUrl = `${$vars.STORAGE_BUCKET_URL}/${path}`;

return [{
  json: {
    schema_id: row.id,
    lead_id: ctx.lead_id,
    diagnostic_id: ctx.diagnostic_id,
    html_content: ctx.html_content,
    upload_path: path,
    public_url: publicUrl,
    tokens_in: ctx.tokens_in,
    tokens_out: ctx.tokens_out,
    api_cost_usd: ctx.api_cost_usd
  }
}];

